def adapt(path):
    from rdkit import Chem
    from rdkit.Chem import Descriptors, rdMolDescriptors, Crippen, Lipinski
    import re

    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            raw = f.read(100000)
    except Exception as e:
        return {'text': 'Could not read molecular file: ' + str(e)}

    mol = None
    source = ''
    for line in raw.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        candidates = [line, line.split()[0]]
        for candidate in candidates:
            try:
                mol = Chem.MolFromSmiles(candidate)
            except Exception:
                mol = None
            if mol is not None:
                source = candidate
                break
        if mol is not None:
            break
    if mol is None:
        return {'text': 'Could not parse a SMILES molecule from the file. Content: ' + raw[:1000]}

    lines = ['Input SMILES: ' + source]
    try:
        lines.append('Canonical isomeric SMILES: ' + Chem.MolToSmiles(mol, canonical=True, isomericSmiles=True))
        lines.append('Molecular formula: ' + rdMolDescriptors.CalcMolFormula(mol))
    except Exception:
        pass
    try:
        lines.append('Molecular weight: %.2f g/mol; exact mass: %.4f Da' % (Descriptors.MolWt(mol), Descriptors.ExactMolWt(mol)))
        lines.append('Calculated logP: %.2f; topological polar surface area: %.2f Å²' % (Crippen.MolLogP(mol), rdMolDescriptors.CalcTPSA(mol)))
        lines.append('Hydrogen-bond donors: %d; acceptors: %d; rotatable bonds: %d' % (Lipinski.NumHDonors(mol), Lipinski.NumHAcceptors(mol), Lipinski.NumRotatableBonds(mol)))
        lines.append('Heavy atoms: %d; rings: %d; aromatic rings: %d; fraction sp3 carbon: %.2f' % (mol.GetNumHeavyAtoms(), rdMolDescriptors.CalcNumRings(mol), rdMolDescriptors.CalcNumAromaticRings(mol), rdMolDescriptors.CalcFractionCSP3(mol)))
    except Exception:
        pass

    patterns = [
        ('aldehyde', '[CX3H1](=O)[#6]'),
        ('ketone', '[#6][CX3](=O)[#6]'),
        ('carboxylic acid', '[CX3](=O)[OX2H1]'),
        ('ester', '[CX3](=O)[OX2][#6]'),
        ('amide', '[CX3](=O)[NX3]'),
        ('phenol', '[OX2H][c]'),
        ('alcohol', '[OX2H][CX4]'),
        ('ether', '[OD2]([#6])[#6]'),
        ('methoxy group', '[OX2]([CH3])[#6]'),
        ('amine', '[NX3;H0,H1,H2;!$(N-C=O)]'),
        ('nitrile', '[CX2]#N'),
        ('nitro group', '[N+](=O)[O-]'),
        ('thiol', '[SX2H]'),
        ('sulfide', '[SX2]([#6])[#6]'),
        ('alkene', '[C;!a]=[C;!a]'),
        ('alkyne', '[C]#[C]'),
        ('halogen substituent', '[F,Cl,Br,I]'),
        ('benzene ring', 'c1ccccc1'),
    ]
    groups = []
    for name, smarts in patterns:
        try:
            query = Chem.MolFromSmarts(smarts)
            count = len(mol.GetSubstructMatches(query))
            if count:
                groups.append('%s (%d)' % (name, count))
        except Exception:
            pass
    lines.append('Detected structural features: ' + (', '.join(groups) if groups else 'none of the tested common groups'))
    try:
        stereo = Chem.FindMolChiralCenters(mol, includeUnassigned=True)
        if stereo:
            lines.append('Tetrahedral stereocenters (atom index, assignment): ' + str(stereo))
    except Exception:
        pass
    return {'text': '\n'.join(lines)}
